  "designIntent": "Tabs switch client-side panels; LinkTabs navigates between routes. Settings, account, and app sub-navigation are URL-driven, so they need link semantics, prefix/exact matching, and a router-agnostic link component rather than a tablist.",
  "props": [
    {
      "name": "items",
      "type": "LinkTabsItem[]",
      "required": true,
      "description": "Tabs in display order. Each item has label, href, optional exact, icon, and disabled."
    },
    {
      "name": "activeHref",
      "type": "string",
      "required": false,
      "description": "Current pathname used to mark the active tab."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Router link element (Inertia Link, Next Link, react-router Link). Defaults to an anchor."
    },
    {
      "name": "linkHrefProp",
      "type": "'href' | 'to'",
      "required": false,
      "defaultValue": "href",
      "description": "Prop used to pass the destination to linkComponent: href for anchors/Next Link, to for react-router.",
      "enum": [
        "href",
        "to"
      ]
    },
    {
      "name": "variant",
      "type": "'default' | 'underline' | 'rounded'",
      "required": false,
      "defaultValue": "default",
      "description": "Visual style of the tab strip.",
      "enum": [
        "default",
        "underline",
        "rounded"
      ]
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "required": false,
      "defaultValue": "md",
      "description": "Control density.",
      "enum": [
        "sm",
        "md",
        "lg"
      ]
    },
    {
      "name": "label",
      "type": "string",
      "required": false,
      "defaultValue": "Section",
