    },
    {
      "name": "className",
      "type": "string",
      "required": false,
      "description": "Additional CSS classes to apply."
    }
  ],
  "examples": [
    {
      "title": "Settings sub-navigation",
      "code": "<LinkTabs\n  items={[\n    { label: 'Profile', href: '/settings/profile', exact: true },\n    { label: 'Billing', href: '/settings/billing' },\n  ]}\n  activeHref={pathname}\n  linkComponent={Link}\n/>",
      "description": "The active item receives aria-current=\"page\"; prefix matching keeps parent sections active on child routes."
    },
    {
      "title": "Underline strip",
      "code": "<LinkTabs items={items} activeHref={pathname} variant=\"underline\" />"
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use Tabs for route navigation",
      "explanation": "Tabs is a tablist for switching panels in place. Use LinkTabs when the URL changes; screen readers and browser history expect links.",
      "example": "// Avoid\n<Tabs><TabsTrigger value=\"/settings\">Settings</TabsTrigger></Tabs>\n\n// Prefer\n<LinkTabs items={[{ label: 'Settings', href: '/settings' }]} activeHref={pathname} />"
    },
    {
      "title": "Don't hardcode the active state",
      "explanation": "Pass activeHref from the router; the component handles exact vs prefix matching."
    }
  ],
  "accessibility": [
    {
      "feature": "Navigation landmark",
      "implementation": "Renders a nav with an accessible label (default \"Section\")."
    },
    {
      "feature": "Current page",
